307:     this.landDip = damp(this.landDip, 0, 9, dt);
308:     this.recoilPitch = damp(this.recoilPitch, 0, 7, dt);
309:     this.recoilYaw = damp(this.recoilYaw, 0, 7, dt);
310:     this.roll = damp(this.roll, 0, 6, dt);
