312:     if (this.reloadT > 0) {
313:       this.reloadT -= dt;
314:       if (this.reloadT <= 0) {
315:         const need = this.magSize - this.mag;
316:         const take = Math.min(need, this.reserve);
317:         this.mag += take;
318:         this.reserve -= take;
319:         this.reloadT = 0;
