331:     // --- movement -------------------------------------------------
332:     const forward = input.forward || 0;
333:     const strafe = input.strafe || 0;
334:     let wishX = 0, wishZ = 0;
335:     if (forward || strafe) {
336:       const len = Math.hypot(forward, strafe);
337:       const f = forward / len;
338:       const s = strafe / len;
339:       const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
340:       wishX = s * cos - f * sin;
341:       wishZ = -s * sin - f * cos;
342:     }
343: 
344:     const wantsSprint = input.sprint && forward > 0.1 && this.stamina > 1 && !this.ads;
345:     const speed = wantsSprint ? 9.6 : 5.5;
346: 
347:     const accel = this.onGround ? 16 : 4.2;
348:     this.vel.x = damp(this.vel.x, wishX * speed, accel, dt);
349:     this.vel.z = damp(this.vel.z, wishZ * speed, accel, dt);
350: 
351:     if (this.onGround) {
352:       if (input.jump) {
353:         this.vel.y = 7.4;
354:         this.onGround = false;
355:         this.game.audio.jump();
356:       }
357:     }
358:     this.vel.y -= 24 * dt;
359:     this.pos.x += this.vel.x * dt;
360:     this.pos.y += this.vel.y * dt;
361:     this.pos.z += this.vel.z * dt;
362: 
363:     // clamp to map
364:     this.pos.x = clamp(this.pos.x, -220, 220);
365:     this.pos.z = clamp(this.pos.z, -220, 220);
366: 
367:     // terrain
368:     const ground = terrainHeight(this.pos.x, this.pos.z);
369:     if (this.pos.y <= ground) {
370:       if (!this.onGround && this.vel.y < -6) {
371:         this.landDip = Math.min(0.16, Math.abs(this.vel.y) * 0.014);
372:         this.game.audio.land();
373:       }
374:       this.pos.y = ground;
375:       this.vel.y = 0;
376:       this.onGround = true;
377:     }
378: 
379:     this.resolveCollisions(colliders);
380: 
381:     // --- stamina --------------------------------------------------
382:     const movingFast = Math.hypot(this.vel.x, this.vel.z) > 6.4;
383:     if (wantsSprint && movingFast) {
384:       this.stamina = Math.max(0, this.stamina - 20 * dt);
385:     } else {
386:       this.stamina = Math.min(100, this.stamina + 14 * dt);
387:     }
