394:     const bobY = this.onGround ? Math.sin(this.bobPhase * 2) * 0.026 * speedK : 0;
395:     const bobX = this.onGround ? Math.cos(this.bobPhase) * 0.018 * speedK : 0;
396: 
397:     const shakeX = Math.sin(this.t * 91) * this.shake * 0.006;
398:     const shakeY = Math.cos(this.t * 77) * this.shake * 0.006;
399: 
400:     this.camera.position.set(
401:       this.pos.x + bobX,
402:       this.pos.y + this.eye + bobY - this.landDip,
403:       this.pos.z
404:     );
405:     this.camera.rotation.set(
406:       this.pitch + this.recoilPitch + shakeX,
407:       this.yaw + this.recoilYaw + shakeY,
408:       this.roll + bobX * 0.5
409:     );
