411:     // footsteps
412:     if (this.onGround && hspeed > 1.6) {
413:       this.stepPhase += dt * hspeed;
414:       if (this.stepPhase > 2.5) {
415:         this.stepPhase = 0;
416:         this.game.audio.step();
417:       }
418:     }
