420:     // --- viewmodel ------------------------------------------------
421:     const vm = this.viewmodel;
422:     const adsK = this.ads ? 1 : 0;
423:     const base = this.basePos;
424:     const aim = this.adsPos;
425:     vm.position.x = damp(vm.position.x, lerp(base.x, aim.x, adsK) + bobX * 0.35, 14, dt);
426:     vm.position.y = damp(vm.position.y, lerp(base.y, aim.y, adsK) + bobY * 0.5, 14, dt);
427:     vm.position.z = damp(vm.position.z, lerp(base.z, aim.z, adsK) + this.kick * 0.055, 16, dt);
428:     vm.rotation.x = damp(vm.rotation.x, this.kick * -0.09, 18, dt);
429:     vm.rotation.y = damp(vm.rotation.y, (this.ads ? 0 : 0.02) + Math.cos(this.bobPhase) * 0.012 * speedK, 10, dt);
430:     vm.rotation.z = damp(vm.rotation.z, this.ads ? 0 : -bobX * 0.6, 10, dt);
431: 
432:     // reload animation
433:     if (this.reloadT > 0) {
434:       const p = 1 - this.reloadT / RELOAD_TIME;
435:       const dip = Math.sin(clamp(p, 0, 1) * Math.PI);
436:       vm.rotation.x -= dip * 0.7;
437:       vm.position.y -= dip * 0.12;
438:       vm.position.z += dip * 0.04;
439:     }
440: 
441:     // muzzle flash
442:     const flashOn = this.flashT > 0;
443:     this.rifle.flash.visible = flashOn;
444:     if (flashOn) {
445:       this.rifle.flash.material.rotation = rand(0, Math.PI);
446:       this.rifle.flash.scale.setScalar(rand(0.4, 0.62));
447:       this.rifle.flashLight.intensity = 45;
448:     } else {
449:       this.rifle.flashLight.intensity = 0;
450:     }
