455:   resolveCollisions(colliders) {
456:     const r = this.radius;
457:     for (const c of colliders) {
458:       if (this.pos.y + 1.75 < c.minY || this.pos.y > c.maxY) continue;
459: 
460:       if (c.type === 'circle') {
461:         const dx = this.pos.x - c.x;
462:         const dz = this.pos.z - c.z;
463:         const dist = Math.hypot(dx, dz);
464:         const min = c.r + r;
465:         if (dist < min && dist > 0.0001) {
466:           const push = (min - dist) / dist;
467:           this.pos.x += dx * push;
468:           this.pos.z += dz * push;
469:         }
470:         continue;
471:       }
472: 
473:       const nx = clamp(this.pos.x, c.minX, c.maxX);
474:       const nz = clamp(this.pos.z, c.minZ, c.maxZ);
475:       const dx = this.pos.x - nx;
476:       const dz = this.pos.z - nz;
477:       const d2 = dx * dx + dz * dz;
478:       if (d2 > r * r) continue;
479: 
480:       if (d2 > 0.000001) {
481:         const dist = Math.sqrt(d2);
482:         const push = (r - dist) / dist;
483:         this.pos.x += dx * push;
484:         this.pos.z += dz * push;
485:       } else {
486:         // inside the box: eject along the shallowest axis
487:         const left = this.pos.x - c.minX;
488:         const right = c.maxX - this.pos.x;
489:         const back = this.pos.z - c.minZ;
490:         const front = c.maxZ - this.pos.z;
491:         const m = Math.min(left, right, back, front);
