        mesh, mat,
        vel: new THREE.Vector3(Math.cos(a) * Math.cos(b) * speed, Math.sin(b) * speed + 2, Math.sin(a) * Math.cos(b) * speed),
        spin: new THREE.Vector3(rand(-14, 14), rand(-14, 14), rand(-14, 14)),
        life: rand(0.5, 1.1),
